'use client';

import {
    Box,
    Button,
    Divider,
    Notification,
    Paper,
    Stack,
    Text,
    Title,
} from '@mantine/core';
import {
    useForm,
} from '@mantine/form';
import {
    notifications,
} from '@mantine/notifications';
import { IconCheck, IconX } from '@tabler/icons-react';
import { zod4Resolver } from 'mantine-form-zod-resolver';
import { useRouter } from 'next/navigation';
import z from 'zod';

import { PasswordFields } from '@/components/PasswordFields/PasswordFields';
import { authClient } from '@/lib/auth.client';
import { config } from '@/lib/config';
import { toPublicMessage, ValidationError } from '@/lib/errors';

export interface Props {
    token: string;
}

/**
 * Validate the password reset inputs for length and confirmation.
 */
const resetPasswordSchema = z.object({
    password: z.string().min(8, { message: 'Password must be at least 8 characters long' }),
    confirmPassword: z.string().min(1, { message: 'Please confirm your password' }),
}).refine((data) => data.password === data.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
});

/**
 * Render the password reset flow for a user who has a reset token.
 */
export const PasswordResetForm = ({ token }: Props) => {
    const router = useRouter();
    const form = useForm<z.infer<typeof resetPasswordSchema>>({
        initialValues: {
            password: '',
            confirmPassword: '',
        },
        validate: zod4Resolver(resetPasswordSchema),
        validateInputOnBlur: true,
    });

    /**
     * Submit a new password for the provided reset token and surface status via notifications.
     */
    const handleSubmit = async (values: z.infer<typeof resetPasswordSchema>) => {
        const id = notifications.show({
            loading: true,
            title: 'Resetting password',
            message: 'Updating your password...',
            autoClose: false,
            withCloseButton: false,
        });

        try {
            const { status } = await authClient.resetPassword({
                newPassword: values.password,
                token,
            });

            if (!status) {
                throw new ValidationError('Reset password returned an unsuccessful status.', {
                    publicMessage: 'Unable to reset password.',
                    details: {
                        tokenPresent: Boolean(token),
                    },
                });
            }

            notifications.update({
                id,
                color: 'teal',
                title: 'Password updated',
                message: 'Your password has been reset successfully.',
                icon: <IconCheck size={config.notificationIconSize} />,
                loading: false,
                autoClose: config.notificationAutoClose,
            });

            router.push('/footy/auth/signin');
        } catch (error) {
            const message = toPublicMessage(error, 'Unable to reset password.');
            notifications.update({
                id,
                color: 'red',
                title: 'Error',
                message,
                icon: <IconX size={config.notificationIconSize} />,
                loading: false,
                autoClose: false,
                withCloseButton: true,
            });
        }
    };

    if (!token) {
        return (
            <Notification icon={<IconX size={config.notificationIconSize} />} color="red">
                <Text>Password reset link is missing or invalid.</Text>
            </Notification>
        );
    }

    return (
        <Paper w="100%" maw="35rem" p="xl">
            <Stack>
                <Title order={2} mb="xs" w="100%" ta="center">
                    Reset your password
                </Title>
                <Divider mb="xs" />
            </Stack>

            <Box
                component="form"
                onSubmit={form.onSubmit(handleSubmit)}
                noValidate
            >
                <Stack>
                    <PasswordFields
                        passwordLabel="New password"
                        confirmPasswordLabel="Confirm new password"
                        passwordPlaceholder="Enter a new password"
                        confirmPasswordPlaceholder="Re-enter your new password"
                        passwordProps={form.getInputProps('password')}
                        confirmPasswordProps={form.getInputProps('confirmPassword')}
                    />
                    <Button type="submit" fullWidth disabled={!form.isValid()}>
                        Reset password
                    </Button>
                </Stack>
            </Box>
        </Paper>
    );
};

