                layer: 'client',
                component: 'ForgottenPasswordForm',
                action: 'requestPasswordReset',
                route: '/footy/forgottenpassword',
                extra: {
                    email: normalizedEmail,
                },
            });
            notifications.update({
                id,
                color: 'red',
                title: 'Error',
                message: toPublicMessage(err, 'Unable to request a password reset right now.'),
                icon: <IconAlertTriangle size={config.notificationIconSize} />,
                loading: false,
                autoClose: false,
                withCloseButton: true,
            });
        }
    };

    return (
        <Box
            component="form"
            onSubmit={form.onSubmit(handleSubmit)}
            noValidate
        >
            <Stack gap="md">
                <Title order={2} mb="xs" w="100%" ta="center">
                    Forgotten Password
                </Title>
                <Divider mb="xs" />
                <EmailInput
                    label="Email"
                    description={[
                        "If the email is associated with an account, you'll receive a reset link.",
                        "Note that if you use Google or Microsoft sign-in, you won't have a password to reset.",
                    ].join(' ')}
                    required
                    {...form.getInputProps(`email`)}
                />

                <Button type="submit" w="fit-content">
                    Send reset link
                </Button>
            </Stack>
        </Box>
    );
};

const validateForgottenPasswordEmail = (value: string, ctx: z.RefinementCtx) => {
    if (!value) {
        ctx.addIssue({
            code: 'custom',
            message: 'Email is required',
        });
        return;
    }

    if (!z.email().safeParse(value).success) {
        ctx.addIssue({
            code: 'custom',
            message: 'Invalid email',
        });
    }
};

const ForgottenPasswordSchema = z.object({
    email: z.string().trim().toLowerCase().superRefine(validateForgottenPasswordEmail),
});

type ForgottenPasswordInput = z.infer<typeof ForgottenPasswordSchema>;

