99	                    <Divider mb="xs" />
100	                    <EmailInput
101	                        label="Email"
102	                        description={[
103	                            "If the email is associated with an account, you'll receive a reset link.",
104	                            "Note that if you use Google or Microsoft sign-in, you won't have a password to reset.",
105	                        ].join(' ')}
106	                        required
107	                        {...form.getInputProps(`email`)}
108	                    />
109	
110	                    <Button type="submit" w="fit-content">
111	                        Send reset link
112	                    </Button>
113	                </Stack>
114	            </Box>
115	        </Paper>
116	    );
117	};
118	
119	const validateForgottenPasswordEmail = (value: string, ctx: z.RefinementCtx) => {
120	    if (!value) {
121	        ctx.addIssue({
122	            code: 'custom',
123	            message: 'Email is required',
124	        });
125	        return;
126	    }
127	
128	    if (!z.email().safeParse(value).success) {
129	        ctx.addIssue({
130	            code: 'custom',
131	            message: 'Invalid email',
132	        });
133	    }
134	};
135	
136	const ForgottenPasswordSchema = z.object({
137	    email: z.string().trim().toLowerCase().superRefine(validateForgottenPasswordEmail),
138	});
139	
140	type ForgottenPasswordInput = z.infer<typeof ForgottenPasswordSchema>;
