                            lastWon={lastWon}
                            isAuthenticated={isAuthenticated}
                            isAdmin={isAdmin}
                            playerData={playerData}
                            onSendEmail={onSendEmail}
                        />
                    </GridCol>
                    <GridCol span={playerCardsGridColSpan}>
                        <PlayerResults player={player} year={year} record={record} />
                    </GridCol>
