                    </GridCol>
                </Grid>
                <Group>
                    <Paper p="sm" w="auto" withBorder style={{ flex: '1' }}>
                        <PlayerHeatmap data={history} year={year} />
                    </Paper>
                </Group>
            </Stack>
        </Container>
    );
};

