1	'use client';
2	
3	import {
4	    Anchor,
5	    Button,
6	    Checkbox,
7	    Container,
8	    Group,
9	    Paper,
10	    SegmentedControl,
11	    Stack,
12	    Table,
13	    Text,
14	    TextInput,
15	    UnstyledButton,
16	} from '@mantine/core';
17	import {
18	    notifications,
19	} from '@mantine/notifications';
20	import { IconSortAscending, IconSortDescending } from '@tabler/icons-react';
21	import { useRouter } from 'next/navigation';
22	import { useMemo, useState } from 'react';
23	
24	import {
25	    buildInviteEmail,
26	    comparePlayers,
27	    getImpersonationLabel,
28	    getPreferredEmail,
29	    isOnboarded,
30	    type SortDirection,
31	    type SortKey,
32	} from '@/lib/adminPlayer';
33	import { config } from '@/lib/config';
34	import { formatDate } from '@/lib/dates';
35	import { normalizeEmail } from '@/lib/email/normalizeEmail';
36	import { assertOkResponse, toPublicMessage } from '@/lib/errors';
37	import { captureUnexpectedError } from '@/lib/observability/sentry';
38	import { PlayerDataType } from '@/types';
39	import { AddPlayerInviteProxy } from '@/types/actions/CreatePlayer';
40	import type { SendEmailProxy } from '@/types/actions/SendEmail';
41	
42	type FinishedFilter = 'all' | 'finished' | 'active';
43	type AuthFilter = 'all' | 'invited' | 'claimed';
44	
45	const finishedFilterOptions = [
46	    { label: 'All', value: 'all' },
47	    { label: 'Finished', value: 'finished' },
48	    { label: 'Active', value: 'active' },
49	];
50	
51	const authFilterOptions = [
52	    { label: 'All', value: 'all' },
53	    { label: 'Invited', value: 'invited' },
54	    { label: 'Claimed', value: 'claimed' },
55	];
56	
57	export interface Props {
58	    players: PlayerDataType[];
59	    userEmails?: string[];
60	    userIdByEmail?: Record<string, string>;
61	    onAddPlayerInvite: AddPlayerInviteProxy;
62	    onSendEmail: SendEmailProxy;
63	}
64	
65	/**
66	 * Admin table for managing players, invitations, and email verification.
67	 *
68	 * @param props - Component props.
69	 * @param props.players - Players to render in the table.
70	 * @param props.userEmails - Better Auth user emails to determine onboarding status.
71	 * @returns The rendered admin player list table.
72	 */
73	export const AdminPlayerList = ({
74	    players,
75	    userEmails,
76	    userIdByEmail,
77	    onAddPlayerInvite,
78	    onSendEmail,
79	}: Props) => {
80	    const router = useRouter();
81	    const userEmailSet = useMemo(
82	        () => new Set((userEmails ?? [])
83	            .map((email) => normalizeEmail(email)).filter((email) => email.length > 0)),
84	        [userEmails],
85	    );
86	    const [sortKey, setSortKey] = useState<SortKey>('id');
87	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
88	    const [selectedIds, setSelectedIds] = useState<number[]>([]);
89	    const [filter, setFilter] = useState('');
90	    const [filterFinished, setFilterFinished] = useState<FinishedFilter>('all');
91	    const [filterAuth, setFilterAuth] = useState<AuthFilter>('all');
92	
93	    /**
94	     * Filters players by name and the active tri-state filters.
95	     *
96	     * @returns The filtered player list.
97	     */
98	    const filteredPlayers = useMemo(() => {
99	        if (!players) return [];
100	        const trimmedFilter = filter.trim().toLowerCase();
101	        return players.filter((player) => {
102	            if (trimmedFilter && !player.name?.toLowerCase().includes(trimmedFilter)) return false;
103	            if (filterFinished === 'finished' && !player.finished) return false;
104	            if (filterFinished === 'active' && player.finished) return false;
105	            const claimed = isOnboarded(player, userEmailSet);
106	            if (filterAuth === 'claimed' && !claimed) return false;
107	            if (filterAuth === 'invited' && claimed) return false;
108	            return true;
109	        });
110	    }, [players, filter, filterFinished, filterAuth, userEmailSet]);
111	
112	    /**
113	     * Applies sorting to the filtered players.
114	     *
115	     * @returns The sorted player list.
116	     */
117	    const sortedPlayers = useMemo(() => {
118	        const data = [...filteredPlayers];
119	        data.sort((a, b) => comparePlayers(a, b, sortKey, sortDirection, userEmailSet));
120	        return data;
121	    }, [filteredPlayers, sortKey, sortDirection, userEmailSet]);
122	
123	    if (!players) {
124	        return (
125	            <Text>Loading players...</Text>
126	        );
127	    }
128	
129	    if (players.length === 0) {
130	        return (
131	            <Text>No players found.</Text>
132	        );
133	    }
134	
135	    /**
136	     * Selects or clears all visible players.
137	     *
138	     * @param checked - Whether the select-all checkbox is checked.
139	     */
140	    const toggleSelectAll = (checked: boolean) => {
141	        setSelectedIds(checked ? filteredPlayers.map((player) => player.id) : []);
142	    };
143	
144	    /**
145	     * Toggles a single player row selection.
146	     *
147	     * @param playerId - The player ID to toggle.
148	     * @param checked - Whether the checkbox is checked.
149	     */
150	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
151	        setSelectedIds((prev) => (
152	            checked ?
153	                [...prev, playerId] :
154	                prev.filter((id) => id !== playerId)
155	        ));
156	    };
157	
158	    const allSelected = filteredPlayers.length > 0 && selectedIds.length === filteredPlayers.length;
159	    const someSelected = selectedIds.length > 0 && !allSelected;
160	    const hasSelection = selectedIds.length > 0;
161	    const selectedPlayers = players.filter((player) => selectedIds.includes(player.id));
162	
163	    /**
164	     * Renders a sortable header label with the current sort icon.
165	     *
166	     * @param label - Column display label.
167	     * @param key - Column sort key.
168	     * @returns A sortable header element.
169	     */
170	    const renderSortHeader = (label: string, key: SortKey) => (
171	        <UnstyledButton
172	            type="button"
173	            onClick={() => handleSort(key)}
174	            aria-label={`Sort by ${label}`}
175	        >
176	            <Group gap={6} wrap="nowrap">
177	                <Text span>{label}</Text>
178	                {sortKey === key ? (
179	                    sortDirection === 'asc' ?
180	                        <IconSortAscending size={16} aria-hidden="true" focusable={false} /> :
181	                        <IconSortDescending size={16} aria-hidden="true" focusable={false} />
182	                ) : null}
183	            </Group>
184	        </UnstyledButton>
185	    );
186	
187	    /**
188	     * Updates the sort state for the selected column.
189	     *
190	     * @param key - Column sort key.
191	     */
192	    const handleSort = (key: SortKey) => {
193	        if (key === sortKey) {
194	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
195	            return;
196	        }
197	        setSortKey(key);
198	        setSortDirection('asc');
199	    };
200	
201	    /**
202	     * Sends onboarding invites and extra email verifications for the selected
203	     * players. Not expected to called with an empty list since the button is
204	     * disabled, but will handle that case anyway.
205	     *
206	     * @param onboardPlayers - The players to onboard.
207	     * @returns A promise that resolves when onboarding emails are handled.
208	     */
209	    const handleOnboardPlayers = async (onboardPlayers: PlayerDataType[]) => {
210	        const id = notifications.show({
211	            loading: true,
212	            title: 'Onboarding players',
213	            message: 'Sending onboarding emails...',
214	            autoClose: false,
215	            withCloseButton: false,
216	        });
217	
218	        try {
219	            let inviteSent = 0;
220	            let inviteSkipped = 0;
221	            for (const player of onboardPlayers) {
222	                const email = getPreferredEmail(player);
223	                if (!email) {
224	                    inviteSkipped += 1;
225	                } else {
226	                    const inviteLink = await onAddPlayerInvite(player.id, email);
227	                    const html = buildInviteEmail(inviteLink);
228	                    const cc = 'footy@toastboy.co.uk';
229	                    await onSendEmail({
230	                        to: email,
231	                        cc,
232	                        subject: 'Welcome to Toastboy FC!',
233	                        html,
234	                    });
235	                    inviteSent += 1;
236	                }
237	            }
238	
239	            notifications.update({
240	                id,
241	                color: 'teal',
242	                title: 'Onboarding sent',
243	                message: [
244	                    `Invites: ${inviteSent} sent`,
245	                    inviteSkipped ? `${inviteSkipped} skipped` : null,
246	                ].filter(Boolean).join('. ') + '.',
247	                loading: false,
248	                autoClose: config.notificationAutoClose,
249	            });
250	        } catch (err) {
251	            captureUnexpectedError(err, {
252	                layer: 'client',
253	                component: 'AdminPlayerList',
254	                action: 'sendOnboarding',
255	                route: '/footy/admin/players',
256	                extra: {
257	                    selectedCount: selectedIds.length,
258	                },
259	            });
260	            notifications.update({
261	                id,
262	                color: 'red',
263	                title: 'Error',
264	                message: toPublicMessage(err, 'Failed to onboard players.'),
265	                loading: false,
266	                autoClose: false,
267	                withCloseButton: true,
268	            });
269	        }
270	    };
271	
272	    const getUserIdForPlayer = (player: PlayerDataType) => {
273	        const email = normalizeEmail(player.accountEmail);
274	        if (!email) return null;
275	        return userIdByEmail?.[email] ?? null;
276	    };
277	
278	    const handleImpersonatePlayer = async (player: PlayerDataType) => {
279	        const userId = getUserIdForPlayer(player);
280	
281	        // The button should be disabled if there's no userId.
282	
283	        const id = notifications.show({
284	            loading: true,
285	            title: 'Starting impersonation',
286	            message: 'Switching session...',
287	            autoClose: false,
288	            withCloseButton: false,
289	        });
290	
291	        try {
292	            const response = await fetch('/api/auth/admin/impersonate-user', {
293	                method: 'POST',
294	                headers: { 'Content-Type': 'application/json' },
295	                body: JSON.stringify({ userId }),
296	            });
297	
298	            await assertOkResponse(response, {
299	                method: 'POST',
300	                fallbackMessage: 'Failed to impersonate user.',
301	            });
302	
303	            router.refresh();
304	            notifications.update({
305	                id,
306	                color: 'teal',
307	                title: 'Impersonation active',
308	                message: `Now impersonating ${getImpersonationLabel(player)}.`,
309	                loading: false,
310	                autoClose: config.notificationAutoClose,
311	            });
312	        } catch (err) {
313	            const message = toPublicMessage(err, 'Failed to impersonate user.');
314	            notifications.update({
315	                id,
316	                color: 'red',
317	                title: 'Error',
318	                message,
319	                loading: false,
320	                autoClose: false,
321	                withCloseButton: true,
322	            });
323	        }
324	    };
325	
326	    const rows = sortedPlayers.map((player: PlayerDataType) => {
327	        const playerHref = `/footy/player/${encodeURIComponent(player.id || '')}`;
328	        const hasAuthAccount = isOnboarded(player, userEmailSet);
329	        const userId = getUserIdForPlayer(player);
330	
331	        return (
332	            <Table.Tr key={player.id}>
333	                <Table.Td w="2.5rem">
334	                    <Checkbox
335	                        checked={selectedIds.includes(player.id)}
336	                        onChange={(event) => toggleSelectPlayer(player.id, event.currentTarget.checked)}
337	                        aria-label={`Select ${player.name ?? ''}`}
338	                    />
339	                </Table.Td>
340	                <Table.Td w="4rem">
341	                    <Anchor href={playerHref}>{player.id}</Anchor>
342	                </Table.Td>
343	                <Table.Td>
344	                    <Anchor href={playerHref}>{player.name}</Anchor>
345	                </Table.Td>
346	                <Table.Td>{formatDate(player.joined)}</Table.Td>
347	                <Table.Td>{formatDate(player.finished)}</Table.Td>
348	                <Table.Td>{hasAuthAccount ? 'Yes' : 'No'}</Table.Td>
349	                <Table.Td>
350	                    <Button
351	                        size="xs"
352	                        variant="light"
353	                        disabled={!userId}
354	                        onClick={() => handleImpersonatePlayer(player)}
355	                    >
356	                        Impersonate
357	                    </Button>
358	                </Table.Td>
359	            </Table.Tr>
360	        );
361	    });
362	
363	    return (
364	        <Container fluid>
365	            <Paper w="100%" p="xl">
366	                <Stack gap="sm">
367	                    <Text fw={700}>
368	                        {sortedPlayers.length} of {players.length} visible, {selectedIds.length} selected
369	                    </Text>
370	                    <Group justify="space-between" align="center" wrap="wrap" mb="md">
371	                        <Group gap="md" wrap="wrap" align="flex-end">
372	                            <TextInput
373	                                label="Name"
374	                                size="xs"
375	                                placeholder="Filter by name"
376	                                value={filter}
377	                                onChange={(event) => setFilter(event.currentTarget.value)}
378	                            />
379	                            <Stack gap={2}>
380	                                <Text id="finished-filter-label" size="xs" fw={500}>Finished</Text>
381	                                <SegmentedControl
382	                                    aria-labelledby="finished-filter-label"
383	                                    size="xs"
384	                                    data={finishedFilterOptions}
385	                                    value={filterFinished}
386	                                    onChange={(value) => setFilterFinished(value as FinishedFilter)}
387	                                />
388	                            </Stack>
389	                            <Stack gap={2}>
390	                                <Text id="auth-filter-label" size="xs" fw={500}>Auth</Text>
391	                                <SegmentedControl
392	                                    aria-labelledby="auth-filter-label"
393	                                    size="xs"
394	                                    data={authFilterOptions}
395	                                    value={filterAuth}
396	                                    onChange={(value) => setFilterAuth(value as AuthFilter)}
397	                                />
398	                            </Stack>
399	                        </Group>
400	                        <Group gap="xs">
401	                            <Button
402	                                size="xs"
403	                                type="button"
404	                                disabled={!hasSelection}
405	                                onClick={() => handleOnboardPlayers(selectedPlayers)}
406	                            >
407	                                Onboard {selectedPlayers.length} player(s)
408	                            </Button>
409	                        </Group>
410	                    </Group>
411	                    <Table.ScrollContainer minWidth="100%" scrollAreaProps={{ type: 'auto' }}>
412	                        <Table
413	                            striped
414	                            highlightOnHover
415	                            withTableBorder
416	                            withColumnBorders
417	                            w="100%"
418	                            layout="fixed"
419	                        >
420	                            <Table.Caption>Registered players</Table.Caption>
421	                            <Table.Thead>
422	                                <Table.Tr>
423	                                    <Table.Th w="2.5rem">
424	                                        <Checkbox
425	                                            checked={allSelected}
426	                                            indeterminate={someSelected}
427	                                            onChange={(event) => toggleSelectAll(event.currentTarget.checked)}
428	                                            aria-label="Select all players"
429	                                        />
430	                                    </Table.Th>
431	                                    <Table.Th
432	                                        w="3rem"
433	                                        aria-sort={sortKey === 'id' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
434	                                    >
435	                                        {renderSortHeader('ID', 'id')}
436	                                    </Table.Th>
437	                                    <Table.Th
438	                                        w="10rem"
439	                                        aria-sort={sortKey === 'name' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
440	                                    >
441	                                        {renderSortHeader('Name', 'name')}
442	                                    </Table.Th>
443	                                    <Table.Th
444	                                        w="7rem"
445	                                        aria-sort={sortKey === 'joined' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
446	                                    >
447	                                        {renderSortHeader('Joined', 'joined')}
448	                                    </Table.Th>
449	                                    <Table.Th
450	                                        w="7rem"
451	                                        aria-sort={sortKey === 'finished' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
452	                                    >
453	                                        {renderSortHeader('Finished', 'finished')}
454	                                    </Table.Th>
455	                                    <Table.Th
456	                                        w="4rem"
457	                                        aria-sort={sortKey === 'auth' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
458	                                    >
459	                                        {renderSortHeader('Auth', 'auth')}
460	                                    </Table.Th>
461	                                    <Table.Th w="7rem">Impersonate</Table.Th>
462	                                </Table.Tr>
463	                            </Table.Thead>
464	                            <Table.Tbody>{rows}</Table.Tbody>
465	                        </Table>
466	                    </Table.ScrollContainer>
467	                </Stack>
468	            </Paper>
469	        </Container>
470	    );
471	};
