            <MenuDivider />

            <MenuLabel>My Data</MenuLabel>
            <MenuItem
                leftSection={<IconArrowsLeftRight size={14} />}
            >
                <Link className={classes.link} href="/footy/downloadmydata">
                    Download my data
                </Link>
            </MenuItem>
            <MenuItem
