                                size="xs"
                            >
                                {email}
                            </Text>
                        </Flex>

                        <IconChevronRight
                            style={{ width: rem(14), height: rem(14) }} stroke={1.5}
                        />
                    </Group>
                </UnstyledButton>
            </MenuTarget>
            {userMenu}
        </Menu>
    );
};

