14	} from '@mantine/form';
15	import {
16	    notifications,
17	} from '@mantine/notifications';
18	import {
19	    Link,
20	    RichTextEditor,
21	} from '@mantine/tiptap';
22	import { IconAlertTriangle, IconCheck, IconUser } from '@tabler/icons-react';
23	import Highlight from '@tiptap/extension-highlight';
24	import Placeholder from '@tiptap/extension-placeholder';
25	import TextAlign from '@tiptap/extension-text-align';
26	import Underline from '@tiptap/extension-underline';
27	import { useEditor } from '@tiptap/react';
28	import StarterKit from '@tiptap/starter-kit';
29	
30	import { config } from '@/lib/config';
31	import { normalizeEmail } from '@/lib/email/normalizeEmail';
32	import { toPublicMessage } from '@/lib/errors';
33	import { captureUnexpectedError } from '@/lib/observability/sentry';
34	import { PlayerDataEmailDisplayType } from '@/types';
35	import type { SendEmailProxy } from '@/types/actions/SendEmail';
36	
37	import classes from './SendEmailForm.module.css';
38	
39	export interface Props {
40	    opened: boolean;
41	    onClose: () => void;
42	    players: PlayerDataEmailDisplayType[];
43	    onSendEmail: SendEmailProxy;
44	    withinPortal?: boolean;
45	    withOverlay?: boolean;
46	}
47	
48	export const SendEmailForm = ({
49	    opened,
50	    onClose,
51	    players,
52	    onSendEmail,
53	    withinPortal,
54	    withOverlay,
55	}: Props) => {
56	    const form = useForm({
57	        initialValues: {
58	            subject: '',
59	        },
60	    });
61	    const names = players.map(({ name }) => name).join(', ');
62	    const emails = Array.from(new Set(players.flatMap((player) => {
63	        const verifiedExtraEmails = player.extraEmails.filter((playerEmail) => playerEmail.verified);
64	        const preferredExtraEmails = verifiedExtraEmails.length > 0 ? verifiedExtraEmails : player.extraEmails;
65	        return [player.accountEmail, ...preferredExtraEmails.map((playerEmail) => playerEmail.email)];
66	    }).map(normalizeEmail).filter((email) => email.length > 0))).join(',');
67	
68	    const editor = useEditor({
69	        extensions: [
70	            Highlight,
71	            Link,
72	            Placeholder.configure({ placeholder: 'Message text' }),
73	            StarterKit,
74	            TextAlign.configure({ types: ['heading', 'paragraph'] }),
75	            Underline,
76	        ],
77	        content: '',
78	        immediatelyRender: false,
79	    });
80	
81	    if (!editor) return null;
82	
83	    const handleSubmit = async (values: { subject: string }, body: string) => {
84	        const id = notifications.show({
85	            loading: true,
86	            title: 'Sending email',
87	            message: 'Sending email...',
88	            autoClose: false,
89	            withCloseButton: false,
90	        });
91	
92	        try {
93	            await onSendEmail({
94	                to: emails,
95	                subject: values.subject,
96	                html: body,
97	            });
98	
99	            onClose();
100	            notifications.update({
101	                id,
102	                color: 'teal',
103	                title: 'Email sent',
104	                message: 'Email sent successfully',
105	                icon: <IconCheck size={config.notificationIconSize} />,
106	                loading: false,
107	                autoClose: config.notificationAutoClose,
108	            });
109	        } catch (err) {
110	            captureUnexpectedError(err, {
111	                layer: 'client',
112	                component: 'SendEmailForm',
113	                action: 'sendEmail',
114	                route: '/footy/admin/players',
115	                extra: {
116	                    recipientCount: players.length,
117	                },
118	            });
119	            notifications.update({
120	                id,
121	                color: 'red',
122	                title: 'Error',
123	                message: toPublicMessage(err, 'Failed to send email.'),
124	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
125	                loading: false,
126	                autoClose: config.notificationAutoClose,
127	            });
128	        }
129	    };
130	
131	    return (
132	        <Modal
133	            opened={opened}
134	            onClose={onClose}
135	            title="Send Mail to Players"
136	            size="lg"
137	            withinPortal={withinPortal}
138	            withOverlay={withOverlay}
139	        >
140	            <Tooltip label={names} multiline>
141	                <Text size="sm" mt="sm" lineClamp={1}>
142	                    <IconUser size={16} className={classes.users} />
143	                    <strong>To:</strong> {names}
144	                </Text>
145	            </Tooltip>
146	            <Box component="form" onSubmit={form.onSubmit((values) => void handleSubmit(values, editor.getHTML()))}>
147	                <TextInput
148	                    label="Subject"
149	                    {...form.getInputProps('subject')}
150	                    required
151	                    mt="md"
152	                />
153	
154	                <RichTextEditor editor={editor} mt="md">
155	                    <RichTextEditor.Toolbar sticky stickyOffset={60}>
156	                        <RichTextEditor.ControlsGroup>
157	                            <RichTextEditor.Bold />
158	                            <RichTextEditor.Italic />
159	                            <RichTextEditor.Underline />
160	                            <RichTextEditor.Strikethrough />
161	                            <RichTextEditor.ClearFormatting />
162	                            <RichTextEditor.Highlight />
163	                            <RichTextEditor.Code />
164	                        </RichTextEditor.ControlsGroup>
165	
166	                        <RichTextEditor.ControlsGroup>
167	                            <RichTextEditor.H1 />
168	                            <RichTextEditor.H2 />
169	                            <RichTextEditor.H3 />
170	                            <RichTextEditor.H4 />
171	                        </RichTextEditor.ControlsGroup>
172	
173	                        <RichTextEditor.ControlsGroup>
174	                            <RichTextEditor.Blockquote />
175	                            <RichTextEditor.Hr />
176	                            <RichTextEditor.BulletList />
177	                            <RichTextEditor.OrderedList />
178	                        </RichTextEditor.ControlsGroup>
179	
