'use client';

import {
    Box,
    Button,
    Divider,
    Group,
    Image,
    Notification,
    Paper,
    Stack,
    Text,
    Title,
    UnstyledButton,
} from '@mantine/core';
import {
    useForm,
} from '@mantine/form';
import { IconX } from '@tabler/icons-react';
import { zod4Resolver } from 'mantine-form-zod-resolver';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import z from 'zod';

import { PasswordFields } from '@/components/PasswordFields/PasswordFields';
import { authClient, signInWithGoogle, signInWithMicrosoft } from '@/lib/auth.client';
import { config } from '@/lib/config';
import { captureUnexpectedError } from '@/lib/observability/sentry';
import { getPublicBaseUrl } from '@/lib/urls';

export interface Props {
    name: string
    email: string;
    token: string;
}

const ClaimSignupSchema = z.object({
    password: z.string().min(8, { message: 'Password must be at least 8 characters long' }),
    confirmPassword: z.string().min(1, { message: 'Please confirm your password' }),
}).refine((data) => data.password === data.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
});

export const ClaimSignup = ({ name, email, token }: Props) => {
    const [loading, setLoading] = useState(false);
    const [signupError, setSignupError] = useState<string | undefined>(undefined);
    const router = useRouter();
    const redirectPath = `/api/footy/auth/claim/${encodeURIComponent(token)}?redirect=/footy/profile`;
    const socialRedirect = new URL(redirectPath, getPublicBaseUrl()).toString();

    const form = useForm({
        initialValues: {
            password: '',
            confirmPassword: '',
        },
        validate: zod4Resolver(ClaimSignupSchema),
        validateInputOnBlur: true,
    });

    const handleSignUp = async (values: z.infer<typeof ClaimSignupSchema>) => {
        setLoading(true);
        setSignupError(undefined);

        try {
            await authClient.signUp.email({
                name: name,
                email: email,
                password: values.password,
            }, {
                onError: (ctx) => {
                    alert(ctx.error.message);
                },
            });

            router.push(redirectPath);
        } catch (err) {
            captureUnexpectedError(err, {
                layer: 'client',
                action: 'signUpWithEmail',
                component: 'ClaimSignup',
                route: '/claim-signup',
                extra: {
                    redirectPath,
                },
            });
            setSignupError('Something went wrong. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const errorNotification = signupError ? (
        <Notification
            icon={<IconX size={config.notificationIconSize} />}
            color="red"
            onClose={() => setSignupError(undefined)}
        >
            {signupError}
        </Notification>
    ) : null;

    return (
        <Paper w="100%" maw="35rem" p="xl" mt="xl">
            <Stack mb="lg">
                <Title order={2} mb="xs" w="100%" ta="center">
                    Finish creating your login
                </Title>
                <Text ta="center">
                    Your email address &quot;{email}&quot; has been verified. Choose how you want to sign in.
                </Text>
                <Divider mb="xs" />
                <Group justify="center" w="100%" mb="md">
                    <UnstyledButton
                        onClick={() => signInWithGoogle(socialRedirect)}
                        w="fit-content"
                        type="button"
                    >
                        <Image src="/google-signin-button-light.svg" alt="Sign in with Google" w={180} h={40} />
                    </UnstyledButton>
                    <UnstyledButton
                        onClick={() => signInWithMicrosoft(socialRedirect)}
                        w="fit-content"
                        type="button"
                    >
                        <Image src="/microsoft-signin-button-light.svg" alt="Sign in with Microsoft" w={215} h={41} />
                    </UnstyledButton>
                </Group>
                <Divider label="or" labelPosition="center" />
            </Stack>

            <Box
                component="form"
                onSubmit={form.onSubmit(handleSignUp)}
            >
                <Stack>
                    <PasswordFields
                        passwordProps={form.getInputProps('password')}
                        confirmPasswordProps={form.getInputProps('confirmPassword')}
                    />
                    {errorNotification}
                    <Button
                        type="submit"
                        fullWidth
                        loading={loading}
                        disabled={!form.isValid()}
                    >
                        Create login
                    </Button>
                </Stack>
            </Box>
        </Paper>
    );
};

'use client';

import {
    Box,
    Button,
    Divider,
    Paper,
    Stack,
    Title,
} from '@mantine/core';
import {
    useForm,
} from '@mantine/form';
import {
    notifications,
} from '@mantine/notifications';
import { IconAlertTriangle, IconCheck } from '@tabler/icons-react';
import { zod4Resolver } from 'mantine-form-zod-resolver';
import z from 'zod';

import { EmailInput } from '@/components/EmailInput/EmailInput';
import { authClient } from '@/lib/auth.client';
import { config } from '@/lib/config';
import { toPublicMessage } from '@/lib/errors';
import { captureUnexpectedError } from '@/lib/observability/sentry';
import { getPublicBaseUrl } from '@/lib/urls';

export const ForgottenPasswordForm = () => {
    const form = useForm<ForgottenPasswordInput>({
        initialValues: {
            email: '',
        } satisfies ForgottenPasswordInput,
        validate: zod4Resolver(ForgottenPasswordSchema),
        validateInputOnBlur: true,
    });

    const handleSubmit = async (
        values: typeof form.values,
    ) => {
        const normalizedEmail = values.email.trim().toLowerCase();

        const id = notifications.show({
            loading: true,
            title: 'Requesting password reset',
            message: 'Checking for your account...',
            autoClose: false,
            withCloseButton: false,
        });

        try {
            await authClient.requestPasswordReset({
                email: normalizedEmail,
                redirectTo: new URL('/footy/auth/reset-password', getPublicBaseUrl()).toString(),
            });

            notifications.update({
                id,
                color: 'teal',
                title: 'Check your email',
                message: 'If that email is linked to an account, a reset link is on the way.',
                icon: <IconCheck size={config.notificationIconSize} />,
                loading: false,
                autoClose: config.notificationAutoClose,
            });
        } catch (err) {
            captureUnexpectedError(err, {
                layer: 'client',
                component: 'ForgottenPasswordForm',
                action: 'requestPasswordReset',
                route: '/footy/forgottenpassword',
                extra: {
                    email: normalizedEmail,
                },
            });
            notifications.update({
                id,
                color: 'red',
                title: 'Error',
                message: toPublicMessage(err, 'Unable to request a password reset right now.'),
                icon: <IconAlertTriangle size={config.notificationIconSize} />,
                loading: false,
                autoClose: false,
                withCloseButton: true,
            });
        }
    };

    return (
        <Paper w="100%" maw="35rem" p="xl">
            <Box
                component="form"
                onSubmit={form.onSubmit(handleSubmit)}
                noValidate
            >
                <Stack gap="md">
                    <Title order={2} mb="xs" w="100%" ta="center">
                        Forgotten Password
                    </Title>
                    <Divider mb="xs" />
                    <EmailInput
                        label="Email"
                        description={[
                            "If the email is associated with an account, you'll receive a reset link.",
                            "Note that if you use Google or Microsoft sign-in, you won't have a password to reset.",
                        ].join(' ')}
                        required
                        {...form.getInputProps(`email`)}
                    />

                    <Button type="submit" w="fit-content">
                        Send reset link
                    </Button>
                </Stack>
            </Box>
        </Paper>
    );
};

const validateForgottenPasswordEmail = (value: string, ctx: z.RefinementCtx) => {
    if (!value) {
        ctx.addIssue({
            code: 'custom',
            message: 'Email is required',
        });
        return;
    }

    if (!z.email().safeParse(value).success) {
        ctx.addIssue({
            code: 'custom',
            message: 'Invalid email',
        });
    }
};

const ForgottenPasswordSchema = z.object({
    email: z.string().trim().toLowerCase().superRefine(validateForgottenPasswordEmail),
});

type ForgottenPasswordInput = z.infer<typeof ForgottenPasswordSchema>;

'use client';

import {
    Anchor,
    Avatar,
    Badge,
    Box,
    Button,
    Checkbox,
    Divider,
    Flex,
    Paper,
    Select,
    Stack,
    Text,
    TextInput,
    Title,
} from '@mantine/core';
import {
    useForm,
} from '@mantine/form';
import {
    useMounted,
} from '@mantine/hooks';
import {
    notifications,
} from '@mantine/notifications';
import { IconAlertTriangle, IconCheck } from '@tabler/icons-react';
import { zod4Resolver } from 'mantine-form-zod-resolver';
import { PlayerResponse } from 'prisma/generated/enums';
import { useState } from 'react';
import z from 'zod';

import { config } from '@/lib/config';
import { captureUnexpectedError } from '@/lib/observability/sentry';
import {
    InvitationResponseInputSchema,
    SubmitGameInvitationResponseProxy,
} from '@/types/actions/SubmitGameInvitationResponse';
import { GameInvitationResponseDetails } from '@/types/GameInvitationResponseDetails';

const formSchema = InvitationResponseInputSchema.omit({ token: true }).extend({
    comment: z.string().max(127).optional(),
});
type FormValues = z.infer<typeof formSchema>;

const responseOptions = [
    { value: PlayerResponse.Yes, label: 'Yes' },
    { value: PlayerResponse.No, label: 'No' },
    { value: PlayerResponse.Dunno, label: 'Dunno' },
];

/**
 * Responses that players can select themselves in this form.
 */
const playerEditableResponses = new Set<PlayerResponse>([
    PlayerResponse.Yes,
    PlayerResponse.No,
    PlayerResponse.Dunno,
]);

/**
 * Returns the initial response value used by the editable select input.
 *
 * Player invitations can carry admin-only response values (for example
 * `Excused`) that should still be displayed in the summary, but players can
 * only submit Yes/No/Dunno from this form.
 *
 * @param response - Incoming invitation response from query details.
 * @returns The player-editable response value for the form select.
 */
function getInitialPlayerResponse(responseInput: GameInvitationResponseDetails['response']) {
    const response = responseInput &&
        playerEditableResponses.has(responseInput) ? responseInput : PlayerResponse.Yes;

    return response;
}

interface Props {
    details: GameInvitationResponseDetails;
    onSubmitGameInvitationResponse: SubmitGameInvitationResponseProxy;
}

export const GameInvitationResponseForm = ({
    details,
    onSubmitGameInvitationResponse,
}: Props) => {
    const mounted = useMounted();
    const response = getInitialPlayerResponse(details.response);
    const [currentResponse, setCurrentResponse] = useState(details.response);
    const [currentComment, setCurrentComment] = useState(details.comment);
    const [canSubmitWithoutChanges, setCanSubmitWithoutChanges] = useState(!details.response);

    const form = useForm<FormValues>({
        initialValues: {
            response,
            goalie: details.goalie ?? false,
            comment: details.comment ?? '',
        },
        validate: zod4Resolver(formSchema),
        validateInputOnBlur: true,
    });

    /**
     * The form is dirty if the user has changed a field, or if there is no
     * saved response yet. In that case, submission is allowed without
     * interaction so users can quickly confirm the default Yes value. Once a
     * response has been saved, the button should disable again until the form
     * changes.
     */
    const isFormDirty = form.isDirty() || canSubmitWithoutChanges;

    const handleSubmit = async (values: FormValues) => {
        const id = notifications.show({
            loading: true,
            title: 'Saving response',
            message: 'Saving your response...',
            autoClose: false,
            withCloseButton: false,
        });

        try {
            await onSubmitGameInvitationResponse({
                token: details.token,
                response: values.response,
                goalie: values.goalie,
                comment: values.comment?.trim() ?? null,
            });

            setCurrentResponse(values.response);
            setCurrentComment(values.comment?.trim() ?? '');
            setCanSubmitWithoutChanges(false);

            notifications.update({
                id,
                color: 'teal',
                title: 'Response saved',
                message: 'Your response has been updated.',
                icon: <IconCheck size={config.notificationIconSize} />,
                loading: false,
                autoClose: config.notificationAutoClose,
            });
        } catch (error) {
            captureUnexpectedError(error, {
                layer: 'client',
                component: 'GameInvitationResponseForm',
                action: 'submitResponse',
                route: '/footy/game/[id]',
                extra: {
                    playerId: details.playerId,
                    gameDayId: details.gameDayId,
                    response: values.response,
                },
            });
            const message = error instanceof Error ? error.message : 'Failed to save response';
            notifications.update({
                id,
                color: 'red',
                title: 'Error',
                message,
                icon: <IconAlertTriangle size={config.notificationIconSize} />,
                loading: false,
                autoClose: false,
                withCloseButton: true,
            });
        }
    };

    const responseColor = {
        [PlayerResponse.Yes.toString()]: 'green',
        [PlayerResponse.No.toString()]: 'red',
        [PlayerResponse.Dunno.toString()]: 'grey',
    } as const;
    const displayResponse = currentResponse ? (
        <Badge color={responseColor[currentResponse.toString()]} variant="filled" size="sm">
            {currentResponse}
        </Badge>
    ) : (
        <Badge color="grey" variant="filled" size="sm">
            No response yet
        </Badge>
    );
    const displayComment = currentComment ? `("${currentComment}")` : '';
    const playerLink = details.playerLogin ? `/footy/player/${details.playerLogin}` : `/footy/player/${details.playerId}`;

    return (
        <Paper w="100%" maw="35rem" p="xl">
            <Box component="form" onSubmit={form.onSubmit(handleSubmit)}>
                <Stack gap="md">
                    <Title order={2} mb="xs" w="100%" ta="center">
                        {currentResponse ? 'Thanks for Your Response' : 'Enter Your Response'}
                    </Title>
                    <Divider mb="xs" />
                    <Flex align="center" gap="md" wrap="wrap">
                        <Avatar
                            src={`/api/footy/player/${details.playerId}/mugshot`}
                            alt={details.playerName}
                            size={48}
                            radius="xl"
                        />
                        <Anchor href={playerLink}>{details.playerName}</Anchor>: {displayResponse} {displayComment}
                    </Flex>
                    <Select
                        label="Response"
                        data={responseOptions}
                        value={form.values.response}
                        /* v8 ignore next -- allowDeselect={false} means value is never null */
                        onChange={(value) => form.setFieldValue('response', (value ?? PlayerResponse.Yes))}
                        allowDeselect={false}
                    />
                    <Checkbox
                        label="Goalie"
                        {...form.getInputProps('goalie', { type: 'checkbox' })}
                    />
                    <TextInput
                        label="Optional comment/excuse"
                        maxLength={127}
                        {...form.getInputProps('comment')}
                    />
                    <Button type="submit" w="fit-content" loading={!mounted} disabled={!isFormDirty}>
                        Save Response
                    </Button>
                    <Text mt="xl">
                        You can change it later if you need to, even if the teams have been picked - either by
                        clicking on the link in the email you received, or by logging in to the site at{' '}
                        <Anchor href={`/footy/game/${details.gameDayId}`}>the game page</Anchor>. If you
                        can&apos;t get to a computer, message Jon on{' '}
                        <strong>{config.organiserPhoneNumber}</strong>.
                    </Text>
                </Stack>
            </Box>
        </Paper>
    );
};

