5	} from '@mantine/core';
6	import { Metadata } from 'next';
7	import { notFound, permanentRedirect } from 'next/navigation';
8	import { TableNameSchema } from 'prisma/zod/schemas';
9	import { cache } from 'react';
10	import z from 'zod';
11	
12	import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
13	import { TitleWithYearDropdown } from '@/components/TitleWithYearDropdown/TitleWithYearDropdown';
14	import { WinnersTable } from '@/components/WinnersTable/WinnersTable';
15	import { getYearName } from '@/lib/tables';
16	import playerRecordService from '@/services/PlayerRecord';
17	import { FootyChannel } from '@/types/FootyChannel';
18	
19	interface PageProps {
20	    searchParams?: Promise<{
21	        year?: string;
22	    }>;
23	}
24	
25	/**
26	 * Resolves and validates the `year` parameter from the given search parameters,
27	 * ensuring it is a valid integer and exists in the list of all available years.
28	 * If the year is invalid or not found, triggers a 404 response. If the current
29	 * URL does not match the canonical URL for the resolved year, performs a
30	 * permanent redirect to the canonical URL.
31	 *
32	 * @param searchParams - The search parameters from the page props, possibly
33	 * containing a `year` value.
34	 * @returns An object containing the validated `year` and the list of all
35	 * available years.
36	 *
37	 * @throws Triggers `notFound()` if the year is invalid or not present in the
38	 * list of years.
39	 * @throws Triggers `permanentRedirect()` if the current URL does not match the
40	 * canonical URL.
41	 */
42	const unpackParams = cache(async (
43	    searchParams: PageProps['searchParams'],
44	) => {
45	    const resolvedSearchParams = await searchParams;
46	    const allYears = await playerRecordService.getAllYears({
47	        completed: true,
48	        mostRecentFirst: true,
49	    });
50	    const yearResult = z.coerce.number().int().min(0).safeParse(resolvedSearchParams?.year ?? 0);
51	    const year = yearResult.success ? yearResult.data : undefined;
52	    if (year === undefined || !allYears.includes(year)) notFound();
53	
54	    const canonicalSearch = year ? `?year=${year}` : '';
55	    const canonicalUrl = `/footy/winners${canonicalSearch}`;
56	    const currentSearch = resolvedSearchParams?.year ? `?year=${resolvedSearchParams.year}` : '';
57	    const currentUrl = `/footy/winners${currentSearch}`;
58	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
59	
60	    return { year, allYears };
61	});
62	
63	/**
64	 * Generates metadata for the table page.
65	 * @param props - The page properties containing params and searchParams
66	 * @param props.params - The route parameters
67	 * @param props.searchParams - The search query parameters
68	 * @returns A promise that resolves to the page metadata with the qualified
69	 * table name as title
70	 */
71	export async function generateMetadata(props: PageProps): Promise<Metadata> {
72	    const { year } = await unpackParams(props.searchParams);
73	
74	    return {
75	        title: `${getYearName(year)} Winners`,
76	    };
77	}
78	
79	const WinnersPage = async (props: PageProps) => {
80	    const { year, allYears } = await unpackParams(props.searchParams);
81	
82	    const winners = await Promise.all(TableNameSchema.options.map(async (table) => {
83	        const records = await playerRecordService.getWinners(table, year);
84	        return { table, records };
85	    }));
86	
87	    return (
88	        <Stack align="stretch" justify="center" gap="md">
89	            <AutoRefresh channels={FootyChannel.Results} />
90	            <Group justify="center" w="100%" mb="xl">
91	                <TitleWithYearDropdown
92	                    order={1}
93	                    title="Winners: "
94	                    year={year}
95	                    validYears={allYears}
96	                />
97	            </Group>
98	            <Flex wrap="wrap" gap="md" justify="center" align="stretch" w="100%">
99	                {
100	                    winners.map(({ table, records }) => {
101	                        return (
102	                            <WinnersTable table={table} records={records} key={table} />
103	                        );
104	                    })
105	                }
106	            </Flex>
107	        </Stack>
108	    );
109	};
110	
111	export default WinnersPage;
